// Defensive check: ensure data was received from GitHub API
const inputData = $input.first()?.json || {};
const rawItems = inputData.items || [];

if (!Array.isArray(rawItems) || rawItems.length === 0) {
  return [{
    json: {
      error: true,
      status: inputData.status || 500,
      message: inputData.message || 'No repository data returned from GitHub API (Rate limit or network error).',
      timestamp: new Date().toISOString()
    }
  }];
}

// Keep only Top 5 repositories and reshape schema
const top5 = rawItems.slice(0, 5).map((repo, index) => ({
  rank: index + 1,
  id: repo.id,
  name: repo.name,
  full_name: repo.full_name,
  owner: repo.owner?.login || 'unknown',
  description: repo.description || 'No description provided.',
  url: repo.html_url,
  stars: repo.stargazers_count || 0,
  forks: repo.forks_count || 0,
  open_issues: repo.open_issues_count || 0,
  language: repo.language || 'Markdown / Docs',
  created_at: repo.created_at,
  updated_at: repo.updated_at,
  is_top_leader: index === 0
}));

// We output the top leader for secondary enrichment call
return top5.map(item => ({ json: item }));

const enrichedRelease = $input.first()?.json || {};
const previousNodeData = $('Code: Filter & Reshape Top 5').all();

// Extract primary enriched leader
const leader = previousNodeData[0]?.json || {};
const hasValidRelease = enrichedRelease.tag_name && !enrichedRelease.error;

const enrichedLeader = {
  ...leader,
  latest_release: hasValidRelease ? {
    tag: enrichedRelease.tag_name,
    name: enrichedRelease.name || enrichedRelease.tag_name,
    published_at: enrichedRelease.published_at,
    author: enrichedRelease.author?.login || 'Maintainer',
    html_url: enrichedRelease.html_url
  } : null,
  has_release_info: !!hasValidRelease,
  briefing_date: new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'short', day: 'numeric' }),
  all_top_5: previousNodeData.map(i => i.json)
};

return [{ json: enrichedLeader }];

