parameters.jsCode:
// Fallback handler when API calls fail or return errors
const item = $input.first()?.json || {};
const isError = item.error || item.status >= 400 || !item.items;

if (isError) {
  return [{
    json: {
      status: 'FALLBACK_TRIGGERED',
      errorMessage: item.message || 'External API threshold/rate limit reached.',
      timestamp: new Date().toISOString(),
      digest: 'Notice: Third-party API is temporarily degraded. The morning digest will automatically retry on the next hourly schedule.'
    }
  }];
}

return [];

